package com.pawmatch.recommendation.adapter.in.web;

import java.math.BigDecimal;
import java.time.Instant;
import java.util.List;
import java.util.UUID;
import java.util.function.Function;

import com.fasterxml.jackson.annotation.JsonInclude;
import com.pawmatch.recommendation.domain.RecommendationRun;
import com.pawmatch.recommendation.domain.ScoringResult;

/**
 * A stored recommendation run. Model fields keep the model's vocabulary ({@code breed_id} is the breed slug).
 * Explanation texts (factors, reasons, warnings, notice, unassessed criteria) are generated by the model in Ukrainian.
 */
record RecommendationRunResponse(
        UUID runId,
        UUID sessionId,
        int answersVersion,
        Instant createdAt,
        String modelVersion,
        String modelType,
        String scoreMeaning,
        BigDecimal minScore,
        String datasetVersion,
        int catalogueBreeds,
        int eligibleBreeds,
        int aboveThreshold,
        List<RecommendedBreedResponse> recommendations,
        String notice,
        List<String> unassessedCriteria,
        List<ExclusionResponse> excluded) {

    /** @param imageUrl resolves a breed slug to its photo URL, or null when it has none */
    static RecommendationRunResponse from(RecommendationRun run, Function<String, String> imageUrl) {
        ScoringResult result = run.result();
        return new RecommendationRunResponse(run.id(), run.sessionId(), run.answersVersion(), run.createdAt(),
                result.modelVersion(), result.modelType(), result.scoreMeaning(), result.minScore(),
                run.datasetVersion(), result.catalogueBreeds(), result.eligibleBreeds(), result.aboveThreshold(),
                result.recommendations().stream()
                        .map(breed -> RecommendedBreedResponse.from(breed, imageUrl.apply(breed.breedId())))
                        .toList(),
                result.notice(), result.unassessedCriteria(),
                result.excluded().stream().map(e -> new ExclusionResponse(e.breedId(), e.reasons())).toList());
    }

    /** {@code image_url} is null when the breed has no photo yet. */
    @JsonInclude(JsonInclude.Include.ALWAYS)
    record RecommendedBreedResponse(String breedId, String breedName, String breedNameEn,
                                    BigDecimal compatibilityIndex, List<FactorResponse> factors, List<String> reasons,
                                    List<String> warnings, String sourceUrl, String imageUrl) {

        static RecommendedBreedResponse from(ScoringResult.ScoredBreed breed, String imageUrl) {
            return new RecommendedBreedResponse(breed.breedId(), breed.breedName(), breed.breedNameEn(),
                    breed.compatibilityIndex(),
                    breed.factors().stream().map(FactorResponse::from).toList(),
                    breed.reasons(), breed.warnings(), breed.sourceUrl(), imageUrl);
        }
    }

    /**
     * @param breedValue   breed rating (number) or size code (string)
     * @param profileValue the user's answer: number, size code or {@code true}
     */
    record FactorResponse(String criterion, String label, Object breedValue, Object profileValue, BigDecimal match,
                          double weight, String explanation) {

        static FactorResponse from(ScoringResult.Factor f) {
            return new FactorResponse(f.criterion(), f.label(), f.breedValue(), f.profileValue(), f.match(),
                    f.weight(), f.explanation());
        }
    }

    record ExclusionResponse(String breedId, List<String> reasons) {
    }
}
